#include "kernel_operator.h"

constexpr int32_t BUFFER_NUM = 2; // 每个队列的张量数量

class KernelMambaReturnY {
public:
    __aicore__ inline KernelMambaReturnY() {}
    __aicore__ inline void Init(GM_ADDR yDiag, GM_ADDR yOff, GM_ADDR yOut, uint32_t totalLength, uint32_t tileNum)
    {
        this->blockLength = totalLength / AscendC::GetBlockNum();
        this->tileNum = tileNum;
        this->tileLength = this->blockLength / tileNum / BUFFER_NUM;

        yDiagGm.SetGlobalBuffer((__gm__ float *)yDiag + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        yOffGm.SetGlobalBuffer((__gm__ float *)yOff + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);
        yOutGm.SetGlobalBuffer((__gm__ float *)yOut + this->blockLength * AscendC::GetBlockIdx(), this->blockLength);

        pipe.InitBuffer(inQueueDiag, BUFFER_NUM, this->tileLength * sizeof(float));
        pipe.InitBuffer(inQueueOff , BUFFER_NUM, this->tileLength * sizeof(float));
        pipe.InitBuffer(outQueue   , BUFFER_NUM, this->tileLength * sizeof(float));
    }

    __aicore__ inline void Process()
    {
        int32_t loopCount = this->tileNum * BUFFER_NUM;
        for (int32_t i = 0; i < loopCount; i++) {
            CopyIn(i);
            Compute(i);
            CopyOut(i);
        }
    }

private:
    __aicore__ inline void CopyIn(int32_t progress)
    {
        AscendC::LocalTensor<float> diagLocal = inQueueDiag.AllocTensor<float>();
        AscendC::LocalTensor<float> offLocal  = inQueueOff.AllocTensor<float>();

        AscendC::DataCopy(diagLocal, yDiagGm[progress * this->tileLength], this->tileLength);
        AscendC::DataCopy(offLocal , yOffGm [progress * this->tileLength], this->tileLength);

        inQueueDiag.EnQue(diagLocal);
        inQueueOff.EnQue(offLocal);
    }

    __aicore__ inline void Compute(int32_t /*progress*/)
    {
        AscendC::LocalTensor<float> diagLocal = inQueueDiag.DeQue<float>();
        AscendC::LocalTensor<float> offLocal  = inQueueOff.DeQue<float>();
        AscendC::LocalTensor<float> outLocal  = outQueue.AllocTensor<float>();

        AscendC::Add(outLocal, diagLocal, offLocal, this->tileLength);

        outQueue.EnQue<float>(outLocal);
        inQueueDiag.FreeTensor(diagLocal);
        inQueueOff.FreeTensor(offLocal);
    }

    __aicore__ inline void CopyOut(int32_t progress)
    {
        AscendC::LocalTensor<float> outLocal = outQueue.DeQue<float>();
        AscendC::DataCopy(yOutGm[progress * this->tileLength], outLocal, this->tileLength);
        outQueue.FreeTensor(outLocal);
    }

private:
    AscendC::TPipe pipe;
    AscendC::TQue<AscendC::TPosition::VECIN,  BUFFER_NUM> inQueueDiag, inQueueOff;
    AscendC::TQue<AscendC::TPosition::VECOUT, BUFFER_NUM> outQueue;
    AscendC::GlobalTensor<float> yDiagGm;
    AscendC::GlobalTensor<float> yOffGm;
    AscendC::GlobalTensor<float> yOutGm;
    uint32_t blockLength;
    uint32_t tileNum;
    uint32_t tileLength;
};

extern "C" __global__ __aicore__ void mamba_return_y_custom(GM_ADDR yDiag, GM_ADDR yOff, GM_ADDR yOut, GM_ADDR workspace, GM_ADDR tiling) {
